package com.fluxisai.proposal;
import java.math.BigDecimal; import java.util.UUID; import jakarta.persistence.*;
@Entity @Table(name="proposal_items") public class ProposalItem { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @Column(name="proposal_id",nullable=false) private UUID proposalId; @Column(name="service_id",nullable=false) private UUID serviceId; @Column(nullable=false,length=500) private String description; @Column(nullable=false,precision=19,scale=4) private BigDecimal quantity; @Column(name="unit_price",nullable=false,precision=19,scale=4) private BigDecimal unitPrice; @Column(nullable=false,precision=19,scale=4) private BigDecimal amount; protected ProposalItem(){} public ProposalItem(UUID p,UUID s,String d,BigDecimal q,BigDecimal u){proposalId=p;serviceId=s;description=d;quantity=q;unitPrice=u;amount=q.multiply(u);} public UUID getId(){return id;} public UUID getProposalId(){return proposalId;} public UUID getServiceId(){return serviceId;} public String getDescription(){return description;} public BigDecimal getQuantity(){return quantity;} public BigDecimal getUnitPrice(){return unitPrice;} public BigDecimal getAmount(){return amount;} }
